import axios from 'axios';

const getBaseURL = () => {
  const hostname = window.location.hostname;
  if (hostname.includes('manus.computer')) {
    // O formato esperado é 3000-id-hash.us1.manus.computer
    const parts = hostname.split('-');
    if (parts.length >= 3) {
      // Reconstroi a URL para a porta 3001
      return `https://3001-${parts[1]}-${parts[2]}.us1.manus.computer/`;
    }
  }
  return 'http://localhost:3001/';
};

export const inAxios = axios.create({ baseURL: getBaseURL() });
